            @endforeach
            @php($returned = $p->rounds->sortByDesc('id')->first())
            @if($p->status === 'rework_pending' && $returned?->status === 'rejected' && !$p->assessments->contains('acceptance_round_id', $returned->id))
            <div class="stack"><h2>Рассмотреть замечание</h2><p class="notice">{{ $returned->reason }}</p><label for="classification-{{ $p->id }}">Основание следующего шага</label><select id="classification-{{ $p->id }}" wire:model="classifications.{{ $p->id }}"><option value="">Выберите основание</option><option value="service_defect">Дефект или незавершённый согласованный объём — за счёт компании</option><option value="additional_scope">Новый объём — требуется согласование с клиентом</option></select><label for="evidence-{{ $p->id }}">Проверенные факты и доказательства</label><textarea id="evidence-{{ $p->id }}" wire:model="assessmentEvidence.{{ $p->id }}" maxlength="20000"></textarea><label for="assessment-{{ $p->id }}">Решение и причина</label><textarea id="assessment-{{ $p->id }}" wire:model="assessmentReasons.{{ $p->id }}" maxlength="5000"></textarea><p class="small muted">Дефект требует нового выезда и нового результата без повторного начисления клиенту. Новый платный объём пока заблокирован финансовым контуром. Это действие не принимает работы за клиента.</p><button class="button primary" wire:click="assessRework({{ $p->id }}, {{ $returned->id }})" wire:loading.attr="disabled" wire:offline.attr="disabled">Записать решение по замечанию</button></div>
            @endif
            @foreach($p->assessments as $assessment)<details><summary>{{ $assessment->classification === 'service_defect' ? 'Устранение за счёт компании' : 'Новый объём требует согласования' }} · {{ $assessment->actor->name }}</summary><p class="preline">{{ $assessment->evidence }}</p><p class="preline">{{ $assessment->reason }}</p><p class="small muted">{{ $assessment->created_at->timezone($requestRecord->site->timezone)->format('d.m.Y H:i') }}</p></details>@endforeach
        </section>
        @endforeach
        <section class="card"><details><summary>Отменить заявку</summary><p>Незавершённые выезды будут отменены или прерваны. Приёмка не выполняется.</p><label for="cancelReason">Причина</label><textarea id="cancelReason" wire:model="cancelReason" rows="3"></textarea><button class="button danger" wire:click="cancel" wire:confirm="Отменить заявку и остановить её незавершённые выезды?" wire:loading.attr="disabled">Отменить заявку</button></details></section>
        @endif
